    {
      "claim": "Open-source ecosystems currently function as free R&D departments for incumbents who offload the social costs of workforce displacement onto the public.",
      "targets": ["AN-20"]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Entry-level hiring slowdowns are a direct consequence of AI-driven automation strategies rather than broader macroeconomic cycles.",
